import json
import os
import sys
from collections import defaultdict
import statistics

DATA_FILE = "/root/autodl-tmp/structfuse/full_m1_data/all.jsonl"
OUT_DIR = "/root/autodl-tmp/structfuse/artifacts"
OUT_FILE = os.path.join(OUT_DIR, "plan006_full_scalability.json")

os.makedirs(OUT_DIR, exist_ok=True)

# Per-repo accumulators
repo_times = defaultdict(list)          # extraction_time_s
repo_errors = defaultdict(list)         # error field (None=success)
repo_has_struct = defaultdict(list)     # bool: has structural data
repo_connected_not_gold = defaultdict(list)  # ratio per instance
repo_instance_count = defaultdict(int)
repo_github = {}

total = 0
parse_errors = 0

print("Reading data...", flush=True)
with open(DATA_FILE, 'r') as f:
    for i, line in enumerate(f):
        if i % 5000 == 0:
            print(f"  processed {i} lines...", flush=True)
        line = line.strip()
        if not line:
            continue
        try:
            d = json.loads(line)
        except json.JSONDecodeError:
            parse_errors += 1
            continue

        total += 1
        repo = d.get("repo", "unknown")
        github_repo = d.get("github_repo", "")
        repo_github[repo] = github_repo
        repo_instance_count[repo] += 1

        # Extraction time
        ext_time = d.get("extraction_time_s")
        if ext_time is not None:
            repo_times[repo].append(ext_time)

        # Error/failure
        error = d.get("error")
        repo_errors[repo].append(error)

        # Structural data: has non-empty call_graph or dataflow_paths
        cg = d.get("call_graph", []) or []
        df = d.get("dataflow_paths", []) or []
        has_struct = len(cg) > 0 or len(df) > 0
        repo_has_struct[repo].append(has_struct)

        # Connected-but-not-gold ratio
        gold_files = set(d.get("gold_patch_files", []) or [])
        connected_files = set()
        for entry in cg:
            fp = entry.get("file_path")
            if fp:
                connected_files.add(fp)
        for entry in df:
            sf = entry.get("source_file")
            snk = entry.get("sink_file")
            if sf:
                connected_files.add(sf)
            if snk:
                connected_files.add(snk)

        if connected_files:
            not_gold = connected_files - gold_files
            ratio = len(not_gold) / len(connected_files)
        else:
            ratio = None  # no connected files
        repo_connected_not_gold[repo].append(ratio)

print(f"Total instances: {total}, parse errors: {parse_errors}")

# === Compute statistics ===

def percentile(data, p):
    sorted_d = sorted(data)
    k = (len(sorted_d) - 1) * p / 100
    f = int(k)
    c = f + 1
    if c >= len(sorted_d):
        return sorted_d[f]
    return sorted_d[f] + (k - f) * (sorted_d[c] - sorted_d[f])

def time_stats(times):
    if not times:
        return {"count": 0}
    return {
        "count": len(times),
        "mean": round(statistics.mean(times), 2),
        "median": round(statistics.median(times), 2),
        "p95": round(percentile(times, 95), 2),
        "max": round(max(times), 2),
        "min": round(min(times), 2),
        "total_hours": round(sum(times) / 3600, 2),
    }

# Repo size tiers based on instance count
def get_tier(count):
    if count < 50:
        return "small_lt50"
    elif count < 200:
        return "medium_50_200"
    elif count < 500:
        return "large_200_500"
    else:
        return "xlarge_500plus"

repos = sorted(repo_instance_count.keys())
all_repos = len(repos)

# 1. Processing time distribution
all_times = []
tier_times = defaultdict(list)
per_repo_time_stats = {}

for repo in repos:
    times = repo_times[repo]
    cnt = repo_instance_count[repo]
    tier = get_tier(cnt)
    all_times.extend(times)
    tier_times[tier].extend(times)
    per_repo_time_stats[repo] = {
        "github_repo": repo_github[repo],
        "instance_count": cnt,
        "tier": tier,
        "time_stats": time_stats(times),
    }

# 2. Error/failure rate
all_errors = 0
all_total = 0
tier_errors = defaultdict(int)
tier_total = defaultdict(int)
error_types = defaultdict(int)

for repo in repos:
    cnt = repo_instance_count[repo]
    tier = get_tier(cnt)
    for err in repo_errors[repo]:
        all_total += 1
        tier_total[tier] += 1
        if err is not None:
            all_errors += 1
            tier_errors[tier] += 1
            # Categorize error
            err_str = str(err)[:100]
            if "timeout" in err_str.lower():
                error_types["timeout"] += 1
            elif "memory" in err_str.lower() or "oom" in err_str.lower():
                error_types["memory"] += 1
            else:
                error_types["other"] += 1

# 3. Per-repo instance count distribution
instance_counts = [repo_instance_count[r] for r in repos]
hist_bins = {"lt10": 0, "10_50": 0, "50_200": 0, "200_500": 0, "500plus": 0}
for c in instance_counts:
    if c < 10:
        hist_bins["lt10"] += 1
    elif c < 50:
        hist_bins["10_50"] += 1
    elif c < 200:
        hist_bins["50_200"] += 1
    elif c < 500:
        hist_bins["200_500"] += 1
    else:
        hist_bins["500plus"] += 1

# 4. Structural data rate
all_struct = 0
all_struct_total = 0
tier_struct = defaultdict(int)
tier_struct_total = defaultdict(int)

for repo in repos:
    cnt = repo_instance_count[repo]
    tier = get_tier(cnt)
    for hs in repo_has_struct[repo]:
        all_struct_total += 1
        tier_struct_total[tier] += 1
        if hs:
            all_struct += 1
            tier_struct[tier] += 1

# 5. Connected-but-not-gold ratio
all_cng_ratios = []
tier_cng_ratios = defaultdict(list)

for repo in repos:
    cnt = repo_instance_count[repo]
    tier = get_tier(cnt)
    for r in repo_connected_not_gold[repo]:
        if r is not None:
            all_cng_ratios.append(r)
            tier_cng_ratios[tier].append(r)

def ratio_stats(ratios):
    if not ratios:
        return {"count": 0}
    return {
        "count": len(ratios),
        "mean": round(statistics.mean(ratios), 4),
        "median": round(statistics.median(ratios), 4),
        "p25": round(percentile(ratios, 25), 4),
        "p75": round(percentile(ratios, 75), 4),
        "p95": round(percentile(ratios, 95), 4),
    }

# === Assemble results ===
tiers_list = ["small_lt50", "medium_50_200", "large_200_500", "xlarge_500plus"]

results = {
    "summary": {
        "total_instances": total,
        "total_repos": all_repos,
        "parse_errors": parse_errors,
        "instances_with_structural_data": all_struct,
        "structural_data_rate": round(all_struct / all_struct_total, 4) if all_struct_total > 0 else 0,
        "total_errors": all_errors,
        "error_rate": round(all_errors / all_total, 4) if all_total > 0 else 0,
    },
    "processing_time": {
        "overall": time_stats(all_times),
        "by_tier": {t: time_stats(tier_times[t]) for t in tiers_list},
    },
    "error_analysis": {
        "overall": {
            "total": all_total,
            "errors": all_errors,
            "error_rate": round(all_errors / all_total, 4) if all_total > 0 else 0,
        },
        "by_tier": {
            t: {
                "total": tier_total[t],
                "errors": tier_errors[t],
                "error_rate": round(tier_errors[t] / tier_total[t], 4) if tier_total[t] > 0 else 0,
            }
            for t in tiers_list
        },
        "error_types": dict(error_types),
    },
    "instance_distribution": {
        "histogram": hist_bins,
        "stats": {
            "mean": round(statistics.mean(instance_counts), 1),
            "median": round(statistics.median(instance_counts), 1),
            "min": min(instance_counts),
            "max": max(instance_counts),
            "total_repos": all_repos,
        },
        "top10_repos": sorted(
            [{"repo": r, "github_repo": repo_github[r], "count": repo_instance_count[r]} for r in repos],
            key=lambda x: -x["count"]
        )[:10],
    },
    "structural_data_rate": {
        "overall": {
            "with_struct": all_struct,
            "total": all_struct_total,
            "rate": round(all_struct / all_struct_total, 4) if all_struct_total > 0 else 0,
        },
        "by_tier": {
            t: {
                "with_struct": tier_struct[t],
                "total": tier_struct_total[t],
                "rate": round(tier_struct[t] / tier_struct_total[t], 4) if tier_struct_total[t] > 0 else 0,
            }
            for t in tiers_list
        },
    },
    "connected_not_gold_ratio": {
        "overall": ratio_stats(all_cng_ratios),
        "by_tier": {t: ratio_stats(tier_cng_ratios[t]) for t in tiers_list},
    },
    "tier_definition": {
        "small_lt50": "<50 instances",
        "medium_50_200": "50-199 instances",
        "large_200_500": "200-499 instances",
        "xlarge_500plus": "500+ instances",
    },
}

with open(OUT_FILE, 'w') as f:
    json.dump(results, f, indent=2, ensure_ascii=False)

print(f"\nResults saved to {OUT_FILE}")
print(f"\n=== SUMMARY ===")
print(json.dumps(results["summary"], indent=2))
print(f"\n=== PROCESSING TIME (overall) ===")
print(json.dumps(results["processing_time"]["overall"], indent=2))
print(f"\n=== ERROR ANALYSIS ===")
print(json.dumps(results["error_analysis"], indent=2))
print(f"\n=== INSTANCE DISTRIBUTION ===")
print(json.dumps(results["instance_distribution"]["histogram"], indent=2))
print(json.dumps(results["instance_distribution"]["stats"], indent=2))
print(f"\n=== STRUCTURAL DATA RATE ===")
print(json.dumps(results["structural_data_rate"], indent=2))
print(f"\n=== CONNECTED-NOT-GOLD RATIO ===")
print(json.dumps(results["connected_not_gold_ratio"], indent=2))
PYEOF
echo "Script written."

